using UnityEngine;
using UnityEditor;
using System.IO;
using System.Linq;
using ConRoi.Investigation.V36.R103;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            string msg = "page=" + s.Page + " finalized=" + s.data.finalized + " insufficient=" + s.data.conclusions.All(c => c.choice == 0) + " claim=" + s.data.conclusions[0].claim + " save=" + File.Exists(s.SavePath) + " path=" + s.SavePath;
            r.Log(msg);
            File.WriteAllText("Test/KetQua/investigation_r103/native-ui-state.txt", msg);
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/native-ui.png");
        }
    }
}

